import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { OperationDefinitionModule } from './modules/isa95-bom-operations-model/operation-definition/operation-definition.module';
import { AppModule } from '@/app.module';
import { AppLogger } from '@/common/logger/app-logger';
import { MssqlConfigurationService } from '@/config/database/mssql/abstract.mssql.config.service';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';
import { MaterialDefinitionModule } from '@/modules/isa95-material-model/material/material.module';
import { MaterialClassModule } from '@/modules/isa95-material-model/material-class/material-class.module';
import { PropertyDataTypeModule } from '@/modules/isa95-material-model/shared/property-data-type.module';
import { MssqlDatabaseChecker } from '@/providers/database/mssql/mssql.database.checker';

/**
 *
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule);
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );

  const { urlApi } = app.get(UrlApiConfigService);

  // Main Swagger doc (excluding /isa95-material-model endpoints)
  const mainConfig = new DocumentBuilder()
    .setTitle('master-api Swagger Documentation')
    .setDescription(
      "In this page you'll find all of the necessary informations about the microservice master-api and its legacy/shared endpoints.",
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();
  const mainDocument = SwaggerModule.createDocument(app, mainConfig);
  // Remove all /isa95-material-model endpoints from the main doc
  const isa95Prefix = '/isa95-material-model';
  mainDocument.paths = Object.fromEntries(
    Object.entries(mainDocument.paths).filter(
      ([path]) => !path.startsWith(isa95Prefix),
    ),
  );
  SwaggerModule.setup('api', app, mainDocument);

  // Dedicated Swagger doc for ISA-95 material model endpoints
  const isa95Config = new DocumentBuilder()
    .setTitle('ISA-95 Material Model Swagger Documentation')
    .setDescription(
      'Dedicated Swagger page for ISA-95 Material Model endpoints.',
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();
  const isa95Document = SwaggerModule.createDocument(app, isa95Config, {
    include: [
      MaterialClassModule,
      MaterialDefinitionModule,
      PropertyDataTypeModule,
    ],
    deepScanRoutes: true,
  });
  SwaggerModule.setup('api/isa95-material-model', app, isa95Document);

  // Dedicated Swagger doc for ISA-95 Operation Model endpoints
  const isa95OperationConfig = new DocumentBuilder()
    .setTitle('ISA-95 Operation Model Swagger Documentation')
    .setDescription(
      'Dedicated Swagger page for ISA-95 Operation Model endpoints (Operation Definitions & Segments).',
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();

  const isa95OperationDocument = SwaggerModule.createDocument(
    app,
    isa95OperationConfig,
    {
      include: [OperationDefinitionModule],
      deepScanRoutes: true,
    },
  );

  SwaggerModule.setup('api/isa95-operation-model', app, isa95OperationDocument);
  const databaseConfig = app.get(MssqlConfigurationService);
  const { migrationsWaitDelayMilliseconds, migrationsWaitRetryLimit } =
    databaseConfig;
  const logger = new AppLogger(bootstrap.name);
  const mssqlDatabaseChecker = app.get(MssqlDatabaseChecker);

  await mssqlDatabaseChecker.waitForMigrations(
    logger,
    migrationsWaitDelayMilliseconds,
    migrationsWaitRetryLimit,
  );

  await app.listen(3000);
}
bootstrap();

