import { OperationDefinitionTableRowDto } from './dtos/operation-definition-table-row.dto';
import { OperationDefinition } from './operation-definition.entity';
import { MaterialDefinition } from '@/modules/isa95-material-model/material/internal/material-definition.entity';

@Injectable()
export class OperationDefinitionService {
  public constructor(
    @InjectRepository(OperationDefinition)
    private readonly operationDefinitionRepository: Repository<OperationDefinition>,

    @InjectRepository(MaterialDefinition)
    private readonly materialRepo: Repository<MaterialDefinition>,
  ) {}

  /**
   * Retrieves a distinct list of material codes for dropdown filtering.
   *
   * Business rules:
   * - Always filtered by plant.
   * - If equipment is provided, only materials associated with that equipment
   * in operation definitions are returned.
   * - Results are returned as distinct material codes, sorted alphabetically.
   * @param plant - Plant context (mandatory)
   * @param search - Optional search term (minimum 3 characters). Returns empty list if shorter
   * @param equipment - Optional equipment code used to filter materials
   * @returns Promise resolving to a list of distinct material codes
   */
  public async getDistinctMaterials(
    plant: number,
    search?: string,
    equipment?: string,
  ): Promise<Array<{ code: string }>> {
    if (!search || search.length < 3) {
      return [];
    }

    const qb = this.materialRepo
      .createQueryBuilder('m')
      .distinct(true)
      .innerJoin('m.operationDefinitions', 'od', 'od.plant = :plant', { plant })
      .select('m.code', 'code')
      .andWhere('m.code LIKE :search', { search: `${search}%` });

    if (equipment) {
      qb.andWhere('od.equipment = :equipment', { equipment });
    }

    return qb.orderBy('m.code', 'ASC').take(20).getRawMany();
  }

  /**
   * Retrieves a distinct list of equipment codes for dropdown filtering.
   *
   * Business rules:
   * - Always filtered by plant.
   * - If material code is provided, only equipment associated with that material
   * in operation definitions is returned.
   * - Results are returned as distinct equipment codes, sorted alphabetically.
   * @param plant - Plant context (mandatory)
   * @param materialCode - Optional material code used to filter equipment
   * @returns Promise resolving to a list of distinct equipment codes
   */
  public async getDistinctEquipment(
    plant: number,
    materialCode?: string,
  ): Promise<Array<{ equipment: string }>> {
    const qb = this.operationDefinitionRepository
      .createQueryBuilder('od')
      .distinct(true)
      .select('od.equipment', 'equipment')
      .where('od.plant = :plant', { plant });

    if (materialCode) {
      qb.innerJoin('od.materialDefinition', 'm', 'm.code = :materialCode', {
        materialCode,
      });
    }

    return qb.orderBy('od.equipment', 'ASC').getRawMany();
  }

  /**
   * Retrieves operation definitions for table display.
   * Supports optional filtering by material and/or equipment.
   * @param parameters - Filtering and pagination parameters
   * @returns A promise resolving to a list of operation definition table rows
   */
  public async getOperationDefinitions(
    parameters: GetOperationDefinitionsDto,
  ): Promise<Array<OperationDefinitionTableRowDto>> {
    const { plant, material, equipment, limit = 50, offset = 0 } = parameters;

    const qb = this.operationDefinitionRepository
      .createQueryBuilder('od')
      .innerJoin('od.materialDefinition', 'm')
      .where('od.plant = :plant', { plant })
      .select([
        'od.id AS operationId',
        'm.code AS material',
        'od.equipment AS equipment',
        'od.effectiveStartDate AS effectiveStartDate',
        'od.effectiveEndDate AS effectiveEndDate',
      ]);

    if (material) {
      qb.andWhere('m.code = :material', { material });
    }

    if (equipment) {
      qb.andWhere('od.equipment = :equipment', { equipment });
    }

    return qb
      .orderBy('od.id', 'DESC')
      .limit(limit)
      .offset(offset)
      .getRawMany<OperationDefinitionTableRowDto>();
  }

  /**
   * Retrieves full read-only details of an operation definition.
   * This endpoint is used to populate the operation definition details drawer.
   *
   * Business rule:
   * - Operation Bill ID corresponds to the ERP Identifier of the BOM Definition.
   * @param operationId - Unique identifier of the operation definition
   * @returns A promise resolving to the operation definition details
   */
  public async getOperationDefinitionDetails(
    operationId: number,
  ): Promise<OperationDefinitionDetailsDto | null> {
    const operationDefinitionDetails = await this.operationDefinitionRepository
      .createQueryBuilder('od')

      // Material (mandatory)
      .innerJoin('od.materialDefinition', 'm')

      // Explicit JOIN with BOM Definition based on FK
      .leftJoin('isa95.bom_definition', 'bd', 'bd.id = od.bomDefinitionId')

      .select([
        'od.id AS operationId',
        'm.code AS material',
        'od.version AS version',
        'od.description AS description',
        'od.equipment AS equipment',
        'od.effectiveStartDate AS effectiveStartDate',
        'od.effectiveEndDate AS effectiveEndDate',

        // Operation Bill ID = BOM ERP Identifier
        'bd.erpIdentifier AS operationBillId',

        'od.taskGroupId AS taskGroupId',
        'od.groupCounter AS groupCounter',
      ])
      .where('od.id = :operationId', { operationId })
      .getRawOne<OperationDefinitionDetailsDto>();

    return operationDefinitionDetails ?? null;
  }
}

