    property: MaterialClassProperty,
    languageCode = 'EN',
  ): MaterialClassPropertyItemResponseDto {
    const normalizedLanguageCode = normalizeLanguageCode(languageCode);
    const matchedPropertyDescription = findPreferredDescription(
      property.descriptions,
      normalizedLanguageCode,
    );
    const propertySemanticsJson = toPropertySemanticsJson(
      property.propertySemanticsJson,
    );

    const dto = new MaterialClassPropertyItemResponseDto();
    dto.code = property.code;
    dto.defaultValue =
      typeof propertySemanticsJson.default_value === 'string'
        ? propertySemanticsJson.default_value
        : undefined;
    dto.description = matchedPropertyDescription?.description ?? '';
    dto.externalMapping = property.externalMapping ?? undefined;
    dto.id = property.id;
    dto.isCustom = property.isCustom;
    dto.length = property.length ?? undefined;
    dto.parentMaterialClassPropertyId =
