import { MaterialClassDescription } from './internal/material-class-description.entity';
import { MaterialClassProperty } from './internal/material-class-property.entity';
import { MaterialClass } from './internal/material-class.entity';
import { MaterialClassPropertyService } from './material-class-property.service';
import { MaterialClassController } from './material-class.controller';
import { MaterialClassService } from './material-class.service';

@Module({
  imports: [
    TypeOrmModule.forFeature([
      MaterialClass,
      MaterialClassDescription,
      MaterialClassProperty,
      MaterialProperty,
      MaterialPropertyDescription,
    ]),
  ],
  controllers: [MaterialClassController],
  providers: [MaterialClassService, MaterialClassPropertyService],
  exports: [MaterialClassService, MaterialClassPropertyService],
})
export class MaterialClassModule {}

import {
  ConflictException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DataSource, In, Repository } from 'typeorm';
import { MaterialDefinition } from '../material/internal/material-definition.entity';
import { MaterialPropertyDescription } from '../material/internal/material-property-description.entity';
import { MaterialProperty } from '../material/internal/material-property.entity';
import {
  defaultDescriptionLanguageCode,
  findPreferredDescription,
  normalizeLanguageCode,
  resolveDescriptionLanguageCode,
} from '../shared/helpers/language-description.helper';
import { CreateMaterialClassDto } from './dtos/create-material-class.dto';
import { MaterialClassRelatedMaterialPropertyDto } from './dtos/material-class-related-material-property.dto';
import { MaterialClassRelatedMaterialDto } from './dtos/material-class-related-material.dto';
import { MaterialClassResponseDto } from './dtos/material-class-response.dto';
import { UpdateMaterialClassDto } from './dtos/update-material-class.dto';
import { MaterialClassDescription } from './internal/material-class-description.entity';
import { MaterialClassInheritance } from './internal/material-class-inheritance.entity';
import { MaterialClassProperty } from './internal/material-class-property.entity';
import { MaterialClass } from './internal/material-class.entity';
import { MaterialMaterialClass } from './internal/material-material-class.entity';

@Injectable()
export class MaterialClassService {
  private static buildNotCustomDeleteMessage(code: string): string {
    return `Material class ${code} cannot be deleted because it is not custom`;
  }

  private static buildUsedByMaterialsDeleteMessage(code: string): string {
    return `Material class ${code} cannot be deleted because it is used by one or more materials`;
  }

  private static selectMaterialDescription(
    descriptions:
      | Array<{
          code?: string;
          description: string;
        }>
      | undefined,
    language: string,
  ):
    | {
        code?: string;
        description: string;
      }
    | undefined {
    return findPreferredDescription(descriptions, language);
  }

  private static mapMaterialForClass(
    materialDefinition: MaterialDefinition,
    materialClassId: number,
    language: string,
  ): MaterialClassRelatedMaterialDto {
    const selectedDescription = MaterialClassService.selectMaterialDescription(
      materialDefinition.materialDescriptionByLanguages,
      language,
    );

    const properties = (materialDefinition.materialProperties ?? [])
      .filter((property) => property.materialClassId === materialClassId)
      .sort((left, right) => left.id - right.id)
      .map<MaterialClassRelatedMaterialPropertyDto>((property) => ({
        id: property.id,
        materialClassId: property.materialClassId,
        propertiesJson: property.propertiesJson ?? {},
      }));

    return {
      code: materialDefinition.code?.trim() ?? '',
      description: selectedDescription?.description ?? null,
      descriptionLanguageCode: selectedDescription?.code?.trim().toUpperCase()
        ? selectedDescription.code.trim().toUpperCase()
        : null,
      id: materialDefinition.id,
      plant: materialDefinition.plant,
      properties,
    };
  }

  private static toResponseDto(
    materialClass: MaterialClass,
    languageCode = 'EN',
  ): MaterialClassResponseDto {
    const matchedDescription = findPreferredDescription(
      materialClass.descriptions,
      languageCode,
    );

    return {
      code: materialClass.code,
      description: matchedDescription?.description ?? '',
      id: materialClass.id,
      isCustom: materialClass.isCustom,
      languageCode: resolveDescriptionLanguageCode(
        matchedDescription,
        languageCode,
      ),
      materialClassPropertiesCount:
        materialClass.materialClassProperties?.length ?? 0,
    };
  }

  public constructor(
    @InjectRepository(MaterialClass)
    private readonly materialClassRepository: Repository<MaterialClass>,
    @InjectRepository(MaterialClassDescription)
    private readonly materialClassDescriptionRepository: Repository<MaterialClassDescription>,
    private readonly dataSource: DataSource,
  ) {}

  public async create(
    payload: CreateMaterialClassDto,
  ): Promise<MaterialClassResponseDto> {
    const normalizedCode = payload.code.trim();
    const normalizedLanguageCode = normalizeLanguageCode(payload.languageCode);
    const normalizedDescription = payload.description.trim();

    const existingMaterialClass = await this.materialClassRepository.findOne({
      where: { code: normalizedCode },
    });

    if (existingMaterialClass) {
      throw new ConflictException(
        `Material class with code ${normalizedCode} already exists`,
      );
    }

    const materialClass = await this.dataSource.transaction(async (manager) => {
      const createdMaterialClass = await manager.save(
        MaterialClass,
        manager.create(MaterialClass, {
          code: normalizedCode,
          isCustom: payload.isCustom ?? false,
        }),
      );

      await manager.save(
        MaterialClassDescription,
        manager.create(MaterialClassDescription, {
          code: normalizedLanguageCode,
          description: normalizedDescription,
          materialClassId: createdMaterialClass.id,
        }),
      );

      return manager.findOneOrFail(MaterialClass, {
        where: { id: createdMaterialClass.id },
        relations: ['descriptions', 'materialClassProperties'],
      });
    });

    return MaterialClassService.toResponseDto(
      materialClass,
      normalizedLanguageCode,
    );
  }

  public async findAll(): Promise<Array<MaterialClassResponseDto>> {
    const materialClasses = await this.materialClassRepository.find({
      order: { code: 'ASC' },
      relations: ['descriptions', 'materialClassProperties'],
    });

    return materialClasses.map((materialClass) =>
      MaterialClassService.toResponseDto(materialClass),
    );
  }

  public async findRelatedMaterials(
    materialClassId: number,
    language?: string,
  ): Promise<Array<MaterialClassRelatedMaterialDto> | undefined> {
    const materialClass = await this.materialClassRepository.findOne({
      where: { id: materialClassId },
    });

    if (!materialClass) {
      return undefined;
    }

    const selectedLanguage = normalizeLanguageCode(
      language ?? defaultDescriptionLanguageCode,
    );

    const links = await this.dataSource
      .getRepository(MaterialMaterialClass)
      .find({
        where: { materialClassId },
        order: {
          materialDefinitionId: 'ASC',
        },
        relations: [
          'materialDefinition',
          'materialDefinition.materialDescriptionByLanguages',
          'materialDefinition.materialProperties',
        ],
      });

    const seenMaterialIds = new Set<number>();

    return links
      .map((link) => link.materialDefinition)
      .filter(Boolean)
      .filter((materialDefinition) => {
        if (seenMaterialIds.has(materialDefinition.id)) {
          return false;
        }

        seenMaterialIds.add(materialDefinition.id);
        return true;
      })
      .map((materialDefinition) =>
        MaterialClassService.mapMaterialForClass(
          materialDefinition,
          materialClassId,
          selectedLanguage,
        ),
      );
  }

  public async findOne(id: number): Promise<MaterialClassResponseDto> {
    const materialClass = await this.materialClassRepository.findOne({
      relations: ['descriptions', 'materialClassProperties'],
      where: { id },
    });
    if (!materialClass) {
      throw new NotFoundException(`Material class with id ${id} not found`);
    }
    return MaterialClassService.toResponseDto(materialClass);
  }

  public async update(
    id: number,
    payload: UpdateMaterialClassDto,
  ): Promise<MaterialClassResponseDto> {
    const existingMaterialClass = await this.materialClassRepository.findOne({
      relations: ['descriptions', 'materialClassProperties'],
      where: { id },
    });

    if (!existingMaterialClass) {
      throw new NotFoundException(`Material class with id ${id} not found`);
    }

    const nextCode = payload.code?.trim();
    const nextDescription = payload.description?.trim();
    const normalizedLanguageCode = normalizeLanguageCode(payload.languageCode);

    if (nextCode && nextCode !== existingMaterialClass.code) {
      const codeConflict = await this.materialClassRepository.findOne({
        where: { code: nextCode },
      });

      if (codeConflict && codeConflict.id !== id) {
        throw new ConflictException(
          `Material class with code ${nextCode} already exists`,
        );
      }
    }

    const materialClass = await this.dataSource.transaction(async (manager) => {
      existingMaterialClass.code = nextCode ?? existingMaterialClass.code;
      existingMaterialClass.isCustom =
        payload.isCustom ?? existingMaterialClass.isCustom;

      await manager.save(MaterialClass, existingMaterialClass);

      if (nextDescription) {
        const existingDescription =
          await this.materialClassDescriptionRepository.findOne({
            where: {
              code: normalizedLanguageCode,
              materialClassId: existingMaterialClass.id,
            },
          });

        if (existingDescription) {
          existingDescription.description = nextDescription;
          await manager.save(MaterialClassDescription, existingDescription);
        } else {
          await manager.save(
            MaterialClassDescription,
            manager.create(MaterialClassDescription, {
              code: normalizedLanguageCode,
              description: nextDescription,
              materialClassId: existingMaterialClass.id,
            }),
          );
        }
      }

      return manager.findOneOrFail(MaterialClass, {
        where: { id: existingMaterialClass.id },
        relations: ['descriptions', 'materialClassProperties'],
      });
    });

    return MaterialClassService.toResponseDto(
      materialClass,
      normalizedLanguageCode,
    );
  }

  public async remove(id: number): Promise<void> {
    await this.dataSource.transaction(async (manager) => {
      const existingMaterialClass = await manager.findOne(MaterialClass, {
        where: { id },
      });

      if (!existingMaterialClass) {
        throw new NotFoundException(`Material class with id ${id} not found`);
      }

      if (!existingMaterialClass.isCustom) {
        throw new ConflictException(
          MaterialClassService.buildNotCustomDeleteMessage(
            existingMaterialClass.code,
          ),
        );
      }

      const materialAssignmentCount = await manager.count(
        MaterialMaterialClass,
        {
          where: { materialClassId: id },
        },
      );
      const materialPropertyCount = await manager.count(MaterialProperty, {
        where: { materialClassId: id },
      });

      if (materialAssignmentCount > 0 || materialPropertyCount > 0) {
        throw new ConflictException(
          MaterialClassService.buildUsedByMaterialsDeleteMessage(
            existingMaterialClass.code,
          ),
        );
      }

      const materialClassProperties = await manager
        .getRepository(MaterialClassProperty)
        .find({
          select: ['id'],
          where: { materialClassId: id },
        });
      const materialClassPropertyIds = materialClassProperties.map(
        (property) => property.id,
      );

      if (materialClassPropertyIds.length > 0) {
        await manager.update(
          MaterialClassProperty,
          {
            parentMaterialClassPropertyId: In(materialClassPropertyIds),
          },
          {
            parentMaterialClassPropertyId: null,
          },
        );

        await manager.delete(MaterialPropertyDescription, {
          materialClassPropertyId: In(materialClassPropertyIds),
        });
      }

      await manager.delete(MaterialProperty, { materialClassId: id });
      await manager.delete(MaterialMaterialClass, { materialClassId: id });
      await manager
        .createQueryBuilder()
        .delete()
        .from(MaterialClassInheritance)
        .where('parent_material_class_id = :id', { id })
        .orWhere('child_material_class_id = :id', { id })
        .execute();
      await manager.delete(MaterialClassDescription, { materialClassId: id });
      await manager.delete(MaterialClassProperty, { materialClassId: id });

      const result = await manager.delete(MaterialClass, id);
      if (!result.affected) {
        throw new NotFoundException(`Material class with id ${id} not found`);
      }
    });
  }
}

