import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { DataSource, Like, Repository } from 'typeorm';
import {
  defaultDescriptionLanguageCode,
  normalizeLanguageCode,
} from '../shared/helpers/language-description.helper';
import { GetMaterialDefinitionsQueryDto } from './dtos/get-material-definitions-query.dto';
import { MaterialDefinitionPaginatedResponseDto } from './dtos/material-definition-paginated-response.dto';
import { MaterialDefinitionPropertyInputDto } from './dtos/material-definition-property-input.dto';
import { MaterialDefinitionResponseDto } from './dtos/material-definition-response.dto';
import { MaterialDefinitionSearchQueryDto } from './dtos/material-definition-search-query.dto';
import { MaterialDefinitionSuggestionDto } from './dtos/material-definition-suggestion.dto';
import { MaterialDefinitionMapper } from './helpers/material.mapper';
import { MaterialDefinition } from './internal/material-definition.entity';
import { MaterialProperty } from './internal/material-property.entity';
import { MaterialMaterialClass } from '@/modules/isa95-material-model/material-class/internal/material-material-class.entity';

@Injectable()
export class MaterialDefinitionService {
  public constructor(
    @InjectRepository(MaterialDefinition)
    private readonly materialDefinitionRepository: Repository<MaterialDefinition>,
    private readonly dataSource: DataSource,
  ) {}

  public async findAll(
    query: GetMaterialDefinitionsQueryDto,
  ): Promise<MaterialDefinitionPaginatedResponseDto> {
    const { code, languageCode, limit, page, plant } = query;
    const [items, total] = await this.materialDefinitionRepository.findAndCount(
      {
        order: { code: 'ASC' },
        relations: [
          'materialDescriptionByLanguages',
          'materialMaterialClasses',
          'materialMaterialClasses.materialClass',
          'materialMaterialClasses.materialClass.descriptions',
          'materialProperties',
          'materialProperties.materialClass',
          'materialProperties.materialClass.descriptions',
          'materialProperties.materialClass.materialClassProperties',
          'materialProperties.materialClass.materialClassProperties.descriptions',
        ],
        skip: (page - 1) * limit,
        take: limit,
        where: {
          code: code ? Like(`%${code}%`) : undefined,
          plant,
        },
      },
    );

    return {
      items: items.map((item) =>
        MaterialDefinitionMapper.toResponseDto(item, languageCode),
      ),
      limit,
      page,
      total,
    };
  }

  public async findOne(id: number): Promise<MaterialDefinitionResponseDto> {
    const materialDefinition = await this.materialDefinitionRepository.findOne({
      where: { id },
      relations: [
        'materialDescriptionByLanguages',
        'materialMaterialClasses',
        'materialMaterialClasses.materialClass',
        'materialMaterialClasses.materialClass.descriptions',
        'materialProperties',
        'materialProperties.materialClass',
        'materialProperties.materialClass.descriptions',
        'materialProperties.materialClass.materialClassProperties',
        'materialProperties.materialClass.materialClassProperties.descriptions',
      ],
    });

    if (!materialDefinition) {
      throw new NotFoundException(
        `Material definition with id ${id} not found`,
      );
    }

    return MaterialDefinitionMapper.toResponseDto(materialDefinition);
  }

  public async getSuggestions(
    query: MaterialDefinitionSearchQueryDto,
  ): Promise<Array<MaterialDefinitionSuggestionDto>> {
    const normalizedSearch = `%${query.search.trim().toLowerCase()}%`;
    const normalizedLanguageCode = normalizeLanguageCode(query.languageCode);

    const suggestions = await this.materialDefinitionRepository
      .createQueryBuilder('materialDefinition')
      .leftJoin(
        'materialDefinition.materialDescriptionByLanguages',
        'requestedMaterialDescriptionByLanguage',
        'requestedMaterialDescriptionByLanguage.code = :requestedLanguageCode',
        {
          requestedLanguageCode: normalizedLanguageCode,
        },
      )
      .leftJoin(
        'materialDefinition.materialDescriptionByLanguages',
        'englishMaterialDescriptionByLanguage',
        'englishMaterialDescriptionByLanguage.code = :englishLanguageCode',
        {
          englishLanguageCode: defaultDescriptionLanguageCode,
        },
      )
      .select('materialDefinition.code', 'code')
      .addSelect(
        `COALESCE(requestedMaterialDescriptionByLanguage.description, englishMaterialDescriptionByLanguage.description)`,
        'description',
      )
      .where('materialDefinition.plant = :plant', { plant: query.plant })
      .andWhere(
        '(LOWER(materialDefinition.code) LIKE :search OR EXISTS (SELECT 1 FROM isa95.material_description_by_language descriptionSearch WHERE descriptionSearch.material_definition_id = materialDefinition.id AND descriptionSearch.plant = materialDefinition.plant AND LOWER(descriptionSearch.description) LIKE :search))',
        { search: normalizedSearch },
      )
      .orderBy('materialDefinition.code', 'ASC')
      .take(query.limit)
      .getRawMany<MaterialDefinitionSuggestionDto>();

    return suggestions;
  }

  public async syncMaterialClasses(
    id: number,
    materialClassIds: Array<number>,
    properties?: Array<MaterialDefinitionPropertyInputDto>,
  ): Promise<MaterialDefinitionResponseDto> {
    const materialDefinition = await this.materialDefinitionRepository.findOne({
      where: { id },
    });

    if (!materialDefinition) {
      throw new NotFoundException(
        `Material definition with id ${id} not found`,
      );
    }

    const uniqueMaterialClassIds = [...new Set(materialClassIds)];
    const normalizedPropertiesByClassId = new Map<
      number,
      Record<string, unknown>
    >();

    for (const property of properties ?? []) {
      if (!uniqueMaterialClassIds.includes(property.materialClassId)) {
        throw new BadRequestException(
          `materialClassId ${property.materialClassId} must be present in materialClassIds`,
        );
      }

      normalizedPropertiesByClassId.set(property.materialClassId, {
        ...normalizedPropertiesByClassId.get(property.materialClassId),
        ...property.values,
      });
    }

    await this.dataSource.transaction(async (manager) => {
      const currentProperties = await manager
        .createQueryBuilder(MaterialProperty, 'materialProperty')
        .select([
          'materialProperty.id',
          'materialProperty.materialClassId',
          'materialProperty.materialDefinitionId',
          'materialProperty.plant',
          'materialProperty.propertiesJson',
        ])
        .where('materialProperty.material_definition_id = :id', { id })
        .andWhere('materialProperty.plant = :plant', {
          plant: materialDefinition.plant,
        })
        .orderBy('materialProperty.id', 'ASC')
        .getMany();

      if (uniqueMaterialClassIds.length > 0) {
        const currentRelations = await manager
          .createQueryBuilder(MaterialMaterialClass, 'materialMaterialClass')
          .select([
            'materialMaterialClass.id',
            'materialMaterialClass.materialClassId',
          ])
          .where('materialMaterialClass.material_definition_id = :id', { id })
          .andWhere('materialMaterialClass.plant = :plant', {
            plant: materialDefinition.plant,
          })
          .getMany();

        const currentClassIds = new Set(
          currentRelations.map((relation) => relation.materialClassId),
        );
        const materialClassIdsToAdd = uniqueMaterialClassIds.filter(
          (materialClassId) => !currentClassIds.has(materialClassId),
        );
        const relationIdsToDelete = currentRelations
          .filter(
            (relation) =>
              !uniqueMaterialClassIds.includes(relation.materialClassId),
          )
          .map((relation) => relation.id);

        if (relationIdsToDelete.length > 0) {
          await manager.delete(MaterialMaterialClass, relationIdsToDelete);
        }

        const relationsToCreate = materialClassIdsToAdd.map((materialClassId) =>
          manager.create(MaterialMaterialClass, {
            materialClassId,
            materialDefinitionId: id,
            plant: materialDefinition.plant,
          }),
        );

        if (relationsToCreate.length > 0) {
          await manager.save(relationsToCreate);
        }
      } else {
        await manager.delete(MaterialMaterialClass, {
          materialDefinitionId: id,
          plant: materialDefinition.plant,
        });
      }

      const propertyIdsToDelete = currentProperties
        .filter(
          (materialProperty) =>
            !uniqueMaterialClassIds.includes(materialProperty.materialClassId),
        )
        .map((materialProperty) => materialProperty.id);

      if (propertyIdsToDelete.length > 0) {
        await manager.delete(MaterialProperty, propertyIdsToDelete);
      }

      const currentPropertiesByClassId = new Map(
        currentProperties.map((materialProperty) => [
          materialProperty.materialClassId,
          materialProperty,
        ]),
      );

      const materialPropertiesToSave = [...normalizedPropertiesByClassId].map(
        ([materialClassId, values]) => {
          const existingProperty =
            currentPropertiesByClassId.get(materialClassId);

          if (existingProperty) {
            existingProperty.propertiesJson = {
              ...existingProperty.propertiesJson,
              ...values,
            };

            return existingProperty;
          }

          return manager.create(MaterialProperty, {
            materialClassId,
            materialDefinitionId: id,
            plant: materialDefinition.plant,
            propertiesJson: values,
          });
        },
      );

      if (materialPropertiesToSave.length > 0) {
        await manager.save(MaterialProperty, materialPropertiesToSave);
      }
    });

    return this.findOne(id);
  }
}

import { ApiProperty } from '@nestjs/swagger';

export class PropertyDataTypeResponseDto {
  @ApiProperty({ example: 1 })
  public id: number;

  @ApiProperty({ example: 'BOOLEAN' })
  public code: string;
}

export interface DescriptionByLanguageLike {
  code?: string | null;
  description: string;
}

export const defaultDescriptionLanguageCode = 'EN';

export const normalizeLanguageCode = (languageCode?: string): string => {
  const normalizedLanguageCode = languageCode?.trim().toUpperCase();
  return normalizedLanguageCode || defaultDescriptionLanguageCode;
};

const normalizeStoredLanguageCode = (
  languageCode?: string | null,
): string | undefined => {
  const normalizedLanguageCode = languageCode?.trim().toUpperCase();
  return normalizedLanguageCode || undefined;
};

export const findPreferredDescription = <T extends DescriptionByLanguageLike>(
  descriptions: Array<T> | undefined,
  languageCode?: string,
): T | undefined => {
  const normalizedLanguageCode = normalizeLanguageCode(languageCode);

  return (
    descriptions?.find(
      (description) =>
        normalizeStoredLanguageCode(description.code) ===
        normalizedLanguageCode,
    ) ??
    (normalizedLanguageCode === defaultDescriptionLanguageCode
      ? undefined
      : descriptions?.find(
          (description) =>
            normalizeStoredLanguageCode(description.code) ===
            defaultDescriptionLanguageCode,
        )) ??
    descriptions?.[0]
  );
};

export const resolveDescriptionLanguageCode = (
  description: Pick<DescriptionByLanguageLike, 'code'> | undefined,
  requestedLanguageCode?: string,
): string => {
  return (
    normalizeStoredLanguageCode(description?.code) ??
    normalizeLanguageCode(requestedLanguageCode)
  );
};

