import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';
import { MaterialDtlResponseDTO } from '@/modules/material-dtl/dtos/material-dtl.response.dto';
import { MaterialDTL } from '@/modules/material-dtl/material-dtl.entity';

@Injectable()
export class MaterialDTLService {
  private readonly logger = new AppLogger(MaterialDTLService.name);

  public constructor(
    @InjectRepository(MaterialDTL)
    private readonly materialDTLRepo: Repository<MaterialDTL>,
  ) {}

  public async getMaterialDtlById(
    materialId: string,
    plant: number,
  ): Promise<MaterialDtlResponseDTO> {
    try {
      const material = await this.materialDTLRepo.findOne({
        where: {
          materialId,
          plant,
        },
      });

      if (!material) {
        throw new NotFoundException(
          `material not Found [plant: ${plant}, materialId: ${materialId}]`,
        );
      }

      return material;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve material dtl by ID:[plant: ${plant}, materialId: ${materialId}], ${error.message}`,
      );
      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          'Failed to retrieve material dtl',
        );
      }
      throw error;
    }
  }

  /**
   * Retrieves material details with their BOM numbers for a list of material IDs
   * @param materialIds - Array of material IDs to fetch
   * @param plant - The plant ID
   * @returns Promise resolving to a map of material IDs to their associated BOM numbers (null if no BOM exists)
   */
  public async getMaterialBomNumbers(
    materialIds: Array<string>,
    plant: number,
  ): Promise<Map<string, string | null>> {
    try {
      if (materialIds.length === 0) {
        return new Map();
      }

      // Find all materials with non-null BOM numbers
      const materials = await this.materialDTLRepo.find({
        where: {
          materialId: In(materialIds),
          plant,
        },
        select: ['materialId', 'bomNumber'],
      });

      // Create a map for quick lookup
      return new Map(materials.map((mat) => [mat.materialId, mat.bomNumber]));
    } catch (error) {
      this.logger.error(
        `Failed to retrieve BOM numbers for materials: ${error.message}`,
        error.stack,
      );
      throw new InternalServerErrorException(
        'Failed to retrieve BOM numbers for materials',
      );
    }
  }
}

