import { Injectable, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { CheckMaterialStorageLocationDto } from './dtos/check-material-storage-location.dto';
import { MaterialStorageLocation } from './material-storage-location.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class MaterialStorageLocationService {
  public constructor(
    @InjectRepository(MaterialStorageLocation)
    private readonly materialStorageLocationRepo: Repository<MaterialStorageLocation>,
  ) {}

  public async checkMaterialStorageLocation(
    dto: CheckMaterialStorageLocationDto,
  ): Promise<CheckMaterialStorageLocationDto> {
    const { materialId, plant, storageLocationId } = dto;

    const materialStorageLocation =
      await this.materialStorageLocationRepo.findOne({
        where: {
          materialId,
          plant,
          storageLocationId,
        },
      });

    if (!materialStorageLocation) {
      throw new NotFoundException(
        `Material storage location not found for plant: ${plant}, material ID: ${materialId}, and storage location ID: ${storageLocationId}.`,
      );
    }

    // Return the DTO instead of the whole entity
    return {
      materialId: materialStorageLocation.materialId,
      plant: materialStorageLocation.plant,
      storageLocationId: materialStorageLocation.storageLocationId,
      storbin: materialStorageLocation.storBin,
    };
  }

  public async checkMaterialStorageLocations(
    plant: number,
    materialIds: Array<string>,
    storageLocationIds: Array<string>,
  ): Promise<Array<CheckMaterialStorageLocationDto>> {
    try {
      // Use a query builder to create a batch query
      const materialStorageLocations = await this.materialStorageLocationRepo
        .createQueryBuilder('material_storage_location')
        .where('material_storage_location.plant = :plant', { plant })
        .andWhere(
          'material_storage_location.material_id IN (:...materialIds)',
          { materialIds },
        )
        .andWhere(
          'material_storage_location.storage_location_id IN (:...storageLocationIds)',
          { storageLocationIds },
        )
        .getMany();
      // Map the results to the DTO format and return
      return materialStorageLocations.map((location) => ({
        materialId: location.materialId,
        plant: location.plant,
        storageLocationId: location.storageLocationId,
        storbin: location.storBin,
      }));
    } catch (error) {
      AppLogger.error('Failed to fetch material storage locations', error);
      return [];
    }
  }
}

