/**
 * Pads a number with leading zeros to the specified length.
 * @param n The number to pad.
 * @param l The desired length of the output string.
 * @returns The padded number as a string.
 */
export function pad(n: number, l: number): string {
  return n.toString().padStart(l, '0');
}

/**
 * Extracts the date in yyyyMMdd format from a Date object.
 * @param d The Date object to extract the date from.
 * @returns The date as a string in yyyyMMdd format.
 */
export function extractDate(d: Date): string {
  return `${d.getUTCFullYear()}${pad(d.getUTCMonth() + 1, 2)}${pad(d.getUTCDate(), 2)}`;
}

/**
 * Extracts the time in HHmmss format from a Date object.
 * @param d The Date object to extract the time from.
 * @returns The time as a string in HHmmss format.
 */
export function extractTime(d: Date): string {
  return `${pad(d.getUTCHours(), 2)}${pad(d.getUTCMinutes(), 2)}${pad(d.getUTCSeconds(), 2)}`;
}

