import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { extractDate, extractTime } from './helper/date-time.helper';
import {
  ShiftContext,
  ShiftContextResult,
} from './interfaces/shift-context.interface';
import { ShiftDetails } from './shift-details.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class ShiftDetailsService {
  private readonly logger = new AppLogger(ShiftDetailsService.name);

  public constructor(
    @InjectRepository(ShiftDetails)
    private readonly shiftDetailsRepo: Repository<ShiftDetails>,
  ) {}

  /**
   * Returns the current, previous, and previous-2 shifts for a workcenter and plant at a given UTC datetime.
   * @param plantId Plant ID
   * @param workcenterId Workcenter ID
   * @param now Date object (UTC)
   * @returns ShiftContextResult
   */
  public async getShiftContext(
    plantId: number,
    workcenterId: string,
    now: Date,
  ): Promise<ShiftContextResult | undefined> {
    try {
      // Format date and time as yyyyMMdd and HHmmss
      const currentDate = extractDate(now);
      const currentTime = extractTime(now);
      // Yesterday's date
      const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);
      const yesterdayDate = extractDate(yesterday);

      // Get all shifts for plant/workcenter
      const shifts = await this.shiftDetailsRepo.find({
        where: { plant: plantId, workCenterId: workcenterId },
        order: { startDateTime: 'DESC' },
      });

      // Find current shift
      let currentShift: ShiftContext | null = null;
      for (const shift of shifts) {
        const startDate = extractDate(shift.startDateTime);
        const endDate = extractDate(shift.endDateTime);
        const startTime = extractTime(shift.startDateTime);
        const endTime = extractTime(shift.endDateTime);

        const isCurrentShift =
          // Same-day shift: starts and ends on current date
          (startDate === currentDate &&
            endDate === currentDate &&
            startTime <= currentTime &&
            endTime >= currentTime) ||
          // Overnight shift starting today: ends tomorrow
          (startDate === currentDate &&
            endDate > currentDate &&
            startTime <= currentTime) ||
          // Overnight shift started yesterday: ends today and current time is before end
          (startDate === yesterdayDate &&
            endDate === currentDate &&
            endTime >= currentTime);

        if (isCurrentShift) {
          currentShift = {
            shift: shift.shift,
            startDatetime: shift.startDateTime.toISOString(),
            endDatetime: shift.endDateTime.toISOString(),
          };
          break;
        }
      }

      // Find previous and previous-2 shifts
      const previousShifts: Array<ShiftContext> = [];
      for (const shift of shifts) {
        const startDate = extractDate(shift.startDateTime);
        const endDate = extractDate(shift.endDateTime);
        const endTime = extractTime(shift.endDateTime);

        const isPreviousShift =
          // Same-day shift that ended today before current time
          (startDate === currentDate &&
            endDate === currentDate &&
            endTime < currentTime) ||
          // Overnight shift started yesterday and ended today before current time
          (startDate === yesterdayDate &&
            endDate === currentDate &&
            endTime < currentTime) ||
          // Any shift that ended yesterday (fully completed yesterday)
          endDate === yesterdayDate;

        if (isPreviousShift) {
          previousShifts.push({
            shift: shift.shift,
            startDatetime: shift.startDateTime.toISOString(),
            endDatetime: shift.endDateTime.toISOString(),
          });
          if (previousShifts.length === 2) break;
        }
      }

      if (!currentShift && previousShifts.length === 0) {
        return undefined;
      }

      return {
        currentShift,
        previousShift: previousShifts[0] || null,
        previousPreviousShift: previousShifts[1] || null,
      };
    } catch {
      return undefined;
    }
  }
}

