import {
  Injectable,
  InternalServerErrorException,
  NotFoundException,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { In, Repository } from 'typeorm';
import { MaterialStorageLocation } from '../material-storage-location/material-storage-location.entity';
import { GetStorageLocationDto } from './dtos/get-storage-location.dto';
import { StorageLocationTypeDto } from './dtos/storage-location-type.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { EwmStorageLocationMessage } from '@/common/publish-message/interface/publish-event-ewm-storage-location';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';
import { PoolstockByStorageLocationResponseDTO } from '@/modules/storage-location/dtos/poolstock-by-storage-location-response.dto';
import { StorageLocationResponseDTO } from '@/modules/storage-location/dtos/storage-location.response.dto';
import { StorageLocation } from '@/modules/storage-location/storage-location.entity';

@Injectable()
export class StorageLocationService {
  private readonly logger = new AppLogger(StorageLocationService.name);

  public constructor(
    @InjectRepository(StorageLocation)
    private readonly storageLocationRepo: Repository<StorageLocation>,

    @InjectRepository(MaterialStorageLocation)
    private readonly materialStorageLocationRepository: Repository<MaterialStorageLocation>,

    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  public async getAllStorageLocations(
    plant: number,
  ): Promise<Array<StorageLocationResponseDTO>> {
    try {
      const storageLocations = await this.storageLocationRepo.find({
        where: { plant },
      });

      if (!storageLocations || storageLocations.length === 0) {
        throw new NotFoundException('storageLocations not Found');
      }

      return storageLocations as Array<StorageLocationResponseDTO>;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve storageLocations: ${error.message}`,
      );
      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve storageLocations',
              error,
            );
      throw errorN;
    }
  }

  public async getPoolstockByStorageLocation(
    plant: number,
    storageLocationId: string,
  ): Promise<PoolstockByStorageLocationResponseDTO> {
    try {
      const poolstock = await this.storageLocationRepo.findOne({
        select: ['poolstock'],
        where: {
          plant,
          storageLocationId,
        },
      });

      if (poolstock === undefined || poolstock === null) {
        throw new NotFoundException('Poolstock not found');
      }

      return poolstock;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve poolstock by storage location: ${error.message}`,
      );

      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve poolstock by storage location',
              error,
            );
      throw errorN;
    }
  }

  public async getStorageLocationDetails(
    dto: GetStorageLocationDto,
  ): Promise<{ eccLocation: string; poolstock: boolean }> {
    const { plant, storageLocationId } = dto;

    const storageLocation = await this.storageLocationRepo.findOne({
      where: {
        plant,
        storageLocationId, // Ensure ecc_location matches storage_location_id
      },
    });

    if (!storageLocation) {
      throw new NotFoundException(
        `Storage location with plant: ${plant} and storageLocationId: ${storageLocationId} not found or mismatch in ecc_location.`,
      );
    }

    return {
      eccLocation: storageLocation.eccLocation,
      poolstock: storageLocation.poolstock,
    };
  }

  public async getTypeByPlantAndLocation(
    plant: number,
    storageLocationId: string,
  ): Promise<StorageLocationTypeDto> {
    const storageLocation = await this.storageLocationRepo.findOne({
      where: { plant, storageLocationId },
    });

    if (!storageLocation) {
      throw new NotFoundException(
        `Storage location not found for plant ${plant} and location ${storageLocationId}`,
      );
    }

    // Return only the type field wrapped in the DTO
    const response = new StorageLocationTypeDto();
    response.type = storageLocation.type;

    return response;
  }

  public async getStorageLocationIdByMaterialAndEccLocation(
    plant: number,
    storageLocationId: string,
    materialId: string,
  ): Promise<{ storageLocationId: string }> {
    // If numeric, pad to 18 digits; otherwise use as-is
    const queryMaterialId = /^\d+$/.test(materialId)
      ? materialId.padStart(18, '0')
      : materialId;

    const result = await this.materialStorageLocationRepository
      .createQueryBuilder('materialStorageLocation')
      .innerJoin(
        StorageLocation,
        'storageLocation',
        'storageLocation.plant = materialStorageLocation.plant AND storageLocation.eccLocation = materialStorageLocation.storageLocationId',
      )
      .select('materialStorageLocation.storageLocationId', 'storageLocationId')
      .where('storageLocation.plant = :plant', { plant })
      .andWhere('storageLocation.storageLocationId = :storageLocationId', {
        storageLocationId,
      })
      .andWhere('materialStorageLocation.materialId = :materialId', {
        materialId: queryMaterialId,
      })
      .getRawOne();

    if (!result) {
      throw new NotFoundException(
        'No storage location found with the given criteria',
      );
    }

    return result.storageLocationId;
  }

  public async updateEwmWip(
    plant: number,
    storageLocationId: string,
    isEwmWip: boolean,
  ): Promise<StorageLocationResponseDTO> {
    try {
      // Find the storage location by plant and storageLocationId
      const storageLocation = await this.storageLocationRepo.findOne({
        where: { plant, storageLocationId },
      });

      if (!storageLocation) {
        throw new NotFoundException('Storage location not found');
      }
      const isEwmPublish: boolean = isEwmWip !== storageLocation.isEwmWip;

      // Update the isEwmWip property
      storageLocation.isEwmWip = isEwmWip;

      // Save the updated storage location

      await this.storageLocationRepo.save(storageLocation);
      if (isEwmPublish) {
        const ewmStorageLocationMessage: EwmStorageLocationMessage = {
          message: 'Storage location updated',
        };
        await this.publishMessageService.publishMessage(
          this.eventhubService.topicEwmStorageLocations,
          ewmStorageLocationMessage,
        );
      }

      return storageLocation as StorageLocationResponseDTO;
    } catch (error) {
      this.logger.error(`Failed to update isEwmWip: ${error.message}`);
      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to update isEwmWip',
              error,
            );
      throw errorN;
    }
  }

  public async getStorageLocationsByPlantIds(
    plantIds: Array<number>,
  ): Promise<Record<number, Array<string>>> {
    try {
      const placeholders = plantIds.join(', ');

      const query = `SELECT s.plant AS plant,
       (
           SELECT sl.storage_location_id as storageLocation
           FROM storage_location sl
           WHERE sl.plant = s.plant
             AND sl.is_ewm = 1
             FOR JSON PATH
       ) AS storageLocations
FROM storage_location s
WHERE s.is_ewm = 1
  AND s.plant IN (${placeholders})
GROUP BY s.plant;
`;
      const storageLocations = await this.storageLocationRepo.query(query);

      if (storageLocations.length === 0) {
        throw new NotFoundException(
          `Storage locations with EWM WIP Flow not found [plant: ${plantIds}]`,
        );
      }

      // Grouping by plant
      const result = Object.assign(
        {},
        ...storageLocations.map(
          (row: { plant: number; storageLocations: string }) => ({
            [row.plant]: (
              JSON.parse(row.storageLocations) as Array<{
                storageLocation: string;
              }>
            ).map((item) => item.storageLocation),
          }),
        ),
      );
      return result;
    } catch (error) {
      throw new Error(`Failed to get storage locations: ${error.message}`);
    }
  }

  public async getPoolstockByStorageLocationList(
    plant: number,
    storageLocationIds: Array<string>,
  ): Promise<Record<string, boolean>> {
    try {
      const rawResult = await this.storageLocationRepo.find({
        select: ['poolstock', 'storageLocationId'],
        where: {
          plant,
          storageLocationId: In(storageLocationIds),
        },
      });
      if (rawResult === undefined || rawResult === null) {
        throw new NotFoundException('Poolstock not found');
      }
      const result: Record<string, boolean> = {};

      // Populate the result object using a `for` loop
      for (const item of rawResult) {
        result[item.storageLocationId] = Boolean(item.poolstock); // Ensure poolstock is boolean
      }

      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve poolstock by storage location list : ${error.message}`,
      );

      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve poolstock by storage location',
              error,
            );
      throw errorN;
    }
  }

  public async getTypeByPlantAndLocationList(
    plant: number,
    storageLocationId: Array<string>,
  ): Promise<Record<string, string>> {
    try {
      const rawResult = await this.storageLocationRepo.find({
        select: ['type', 'storageLocationId'],
        where: {
          plant,
          storageLocationId: In(storageLocationId),
        },
      });
      if (rawResult === undefined || rawResult === null) {
        throw new NotFoundException('Poolstock not found');
      }
      const result: Record<string, string> = {};

      if (!rawResult) {
        throw new NotFoundException(
          `Storage location not found for plant ${plant} and location ${storageLocationId}`,
        );
      }
      for (const item of rawResult) {
        result[item.storageLocationId] = item.type; // Ensure poolstock is boolean
      }
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve poolstock by storage location list : ${error.message}`,
      );

      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve poolstock by storage location',
              error,
            );
      throw errorN;
    }
  }

  public async getStorageLocationIdsByPlantAndPoolStock(
    plant: number,
    poolstock: boolean,
  ): Promise<Array<string>> {
    const results = await this.storageLocationRepo.find({
      select: ['storageLocationId'],
      where: {
        plant,
        poolstock,
      },
    });

    return results.map((loc) => loc.storageLocationId);
  }
}

import { DatabaseType } from 'typeorm';
import { MssqlConfigurationService } from '@/config/database/mssql/abstract.mssql.config.service';
/**
 *
 * @param mssqlConfigService
 */
interface ConnectionOptions {
  encrypt: boolean;
}

interface ConnectionExtra {
  trustServerCertificate: boolean;
  authentication?: {
    type: string;
    options: {
      clientId: string;
    };
  };
}

interface BaseProperties {
  type: DatabaseType;
  host: string;
  port: number;
  database: string;
  options: ConnectionOptions;
  synchronize: boolean;
  lazy: boolean;
  autoLoadEntities: boolean;
  extra: ConnectionExtra;
  entities: Array<string>;
  migrations: Array<string>;
  migrationsTableName: string;
}

interface ManagedIdentityProperties extends BaseProperties {
  extra: ConnectionExtra & {
    authentication: {
      type: string;
      options: {
        clientId: string;
      };
    };
  };
}

interface SqlAuthProperties extends BaseProperties {
  username: string;
  password: string;
}

type ConnectionProperties = ManagedIdentityProperties | SqlAuthProperties;
/**
 *
 * @param mssqlConfigService - The configuration service containing MSSQL settings.
 * @returns The connection properties for the database.
 */
export function getDatabaseConnectionProperties(
  mssqlConfigService: MssqlConfigurationService,
): ConnectionProperties {
  const baseProperties: BaseProperties = {
    autoLoadEntities: true,
    database: mssqlConfigService.database,
    entities: mssqlConfigService.entities,
    extra: {
      trustServerCertificate: true,
    },
    host: mssqlConfigService.host,
    lazy: true,
    migrations: mssqlConfigService.migrations,
    migrationsTableName: mssqlConfigService.migrationsTableName,
    options: {
      encrypt: mssqlConfigService.encrypt,
    },
    port: mssqlConfigService.port,
    synchronize: mssqlConfigService.synchronize,
    type: mssqlConfigService.type as DatabaseType,
  };

  if (mssqlConfigService.useManagedIdentity) {
    const managedIdentityProperties: ManagedIdentityProperties = {
      ...baseProperties,
      extra: {
        ...baseProperties.extra,
        authentication: {
          options: {
            clientId: mssqlConfigService.managedIdentityClientId,
          },
          type: 'azure-active-directory-msi-vm',
        },
      },
    };

    return managedIdentityProperties;
  }

  const sqlAuthProperties: SqlAuthProperties = {
    ...baseProperties,
    password: mssqlConfigService.password,
    username: mssqlConfigService.username,
  };

  return sqlAuthProperties;
}

import { InjectDataSource } from '@nestjs/typeorm';
import { DataSource } from 'typeorm';
import { AppLogger } from '@/common/logger/app-logger';

export class MssqlDatabaseChecker {
  public constructor(
    @InjectDataSource()
    private dataSource: DataSource,
  ) {}

  public async pendingMigrations(): Promise<boolean> {
    if (!this.dataSource.isInitialized) {
      this.dataSource = await this.dataSource.initialize();
    }

    return this.dataSource.showMigrations();
  }

  public async waitForMigrations(
    logger: AppLogger,
    waitDelayMilliseconds: number,
    remainingRetries: number,
  ): Promise<void> {
    const isPendingMigrations: boolean = await this.pendingMigrations();
    if (isPendingMigrations && remainingRetries > 0) {
      logger.warn(
        `Waiting for Migrations to be applied (delay: ${waitDelayMilliseconds} ms, remainingRetries: ${remainingRetries})`,
      );

      await new Promise((resolve) => {
        setTimeout(resolve, waitDelayMilliseconds);
      });

      await this.waitForMigrations(
        logger,
        waitDelayMilliseconds,
        remainingRetries - 1,
      );
    } else if (remainingRetries <= 0) {
      throw new Error(`Waiting for migrations timed-out`);
    } else {
      logger.log('Migrations applied [OK]');
    }
  }
}

