import { existsSync, readdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { EntityTarget, ObjectLiteral } from 'typeorm';
import type {
  SeedDataFile,
  SeedDataSchema,
  SeedFieldMapping,
} from '@/seeding/core/seed-runner.types';

const dataFileSuffix = '.seed-data.';
const nodeRequire = createRequire(`${process.cwd()}/package.json`);
const pathModule =
  path ?? (nodeRequire('node:path') as typeof import('node:path'));
const isTsRuntimeMode =
  process.execArgv.some((argument) => argument.includes('ts-node')) ||
  process.execArgv.some((argument) => argument.includes('tsx')) ||
  Boolean(process.argv[1]?.endsWith('.ts')) ||
  Boolean(process.argv[1]?.endsWith('.tsx'));

/**
 * Type guard for non-null objects.
 * @param value Unknown value to evaluate.
 * @returns True when value is an object-like record.
 */
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

/**
 * Validate a non-empty array of strings.
 * @param value Unknown array candidate.
 * @param propertyName Property name for error context.
 * @param filePath Seed file path for error context.
 * @returns Normalized array of strings.
 */
function parseNonEmptyStringArray(
  value: unknown,
  propertyName: string,
  filePath: string,
): Array<string> {
  if (!Array.isArray(value) || value.length === 0) {
    throw new Error(
      `Seed data file "${filePath}" must provide "${propertyName}" as a non-empty string array.`,
    );
  }

  if (
    value.some(
      (entry) => typeof entry !== 'string' || entry.trim().length === 0,
    )
  ) {
    throw new Error(
      `Seed data file "${filePath}" has invalid "${propertyName}" values. Expected non-empty strings.`,
    );
  }

  return value.map((entry) => entry.trim());
}

/**
 * Validate mapping schema configuration for a seed file.
 * @param schema Raw schema configuration.
 * @param filePath Seed file path for error context.
 * @returns Normalized schema object.
 */
function parseSchema(schema: unknown, filePath: string): SeedDataSchema {
  if (!isRecord(schema)) {
    throw new TypeError(
      `Seed data file "${filePath}" must provide "schema" as an object.`,
    );
  }

  const inputKeyColumns = parseNonEmptyStringArray(
    schema.inputKeyColumns,
    'schema.inputKeyColumns',
    filePath,
  );
  const tableKeyColumns = parseNonEmptyStringArray(
    schema.tableKeyColumns,
    'schema.tableKeyColumns',
    filePath,
  );
  const { mapping } = schema;

  if (!isRecord(mapping) || Object.keys(mapping).length === 0) {
    throw new Error(
      `Seed data file "${filePath}" must provide "schema.mapping" as a non-empty object.`,
    );
  }

  const normalizedMapping: Record<string, SeedFieldMapping> = {};

  for (const [targetColumn, fieldMapping] of Object.entries(mapping)) {
    if (targetColumn.trim().length === 0 || !isRecord(fieldMapping)) {
      throw new Error(
        `Seed data file "${filePath}" has an invalid mapping entry for "${targetColumn}".`,
      );
    }

    switch (fieldMapping.type) {
      case 'column': {
        if (
          typeof fieldMapping.sourceColumn !== 'string' ||
          fieldMapping.sourceColumn.trim().length === 0
        ) {
          throw new Error(
            `Seed data file "${filePath}" has invalid column mapping for "${targetColumn}".`,
          );
        }
        normalizedMapping[targetColumn] = {
          sourceColumn: fieldMapping.sourceColumn.trim(),
          type: 'column',
        };
        break;
      }
      case 'constant': {
        normalizedMapping[targetColumn] = {
          type: 'constant',
          value: fieldMapping.value,
        };
        break;
      }
      case 'reference': {
        if (
          typeof fieldMapping.dataFileId !== 'string' ||
          fieldMapping.dataFileId.trim().length === 0
        ) {
          throw new Error(
            `Seed data file "${filePath}" has invalid reference mapping for "${targetColumn}".`,
          );
        }

        const keyColumns = parseNonEmptyStringArray(
          fieldMapping.keyColumns,
          `schema.mapping.${targetColumn}.keyColumns`,
          filePath,
        );
        normalizedMapping[targetColumn] = {
          dataFileId: fieldMapping.dataFileId.trim(),
          keyColumns,
          optional: fieldMapping.optional === true,
          type: 'reference',
        };
        break;
      }
      default: {
        throw new Error(
          `Seed data file "${filePath}" has unsupported mapping type for "${targetColumn}".`,
        );
      }
    }
  }

  let normalizedRelationsToLoad: Array<string> | undefined;

  if (
    schema.tableRelationsToLoad !== undefined &&
    !Array.isArray(schema.tableRelationsToLoad)
  ) {
    throw new TypeError(
      `Seed data file "${filePath}" must provide "schema.tableRelationsToLoad" as a string array when set.`,
    );
  }

  if (
    Array.isArray(schema.tableRelationsToLoad) &&
    schema.tableRelationsToLoad.some(
      (relationName) =>
        typeof relationName !== 'string' || relationName.trim().length === 0,
    )
  ) {
    throw new Error(
      `Seed data file "${filePath}" has invalid values in "schema.tableRelationsToLoad".`,
    );
  }

  if (Array.isArray(schema.tableRelationsToLoad)) {
    normalizedRelationsToLoad = schema.tableRelationsToLoad.map(
      (relationName) => relationName.trim(),
    );
  }

  return {
    inputKeyColumns,
    mapping: normalizedMapping,
    tableKeyColumns,
    tableRelationsToLoad: normalizedRelationsToLoad,
  };
}

/**
 * Validate uniqueness of seed file identifiers.
 * @param fileEntries Loaded seed file descriptors with source paths.
 */
function validateUniqueSeedIds(
  fileEntries: Array<{ filePath: string; seedDataFile: SeedDataFile }>,
): void {
  const firstOccurrenceById = new Map<string, string>();

  for (const fileEntry of fileEntries) {
    const firstOccurrenceFilePath = firstOccurrenceById.get(
      fileEntry.seedDataFile.id,
    );

    if (firstOccurrenceFilePath) {
      throw new Error(
        `Duplicate seed id "${fileEntry.seedDataFile.id}" found in "${firstOccurrenceFilePath}" and "${fileEntry.filePath}".`,
      );
    }

    firstOccurrenceById.set(fileEntry.seedDataFile.id, fileEntry.filePath);
  }
}

/**
 * Resolve a seed table key into a registered TypeORM entity target.
 * @param tableKey Seed table key from JSON seed file.
 * @param entityRegistry Caller-provided table-key-to-entity mapping.
 * @returns Matching TypeORM entity target.
 */
function resolveSeedEntity(
  tableKey: string,
  entityRegistry: ReadonlyMap<string, EntityTarget<ObjectLiteral>>,
): EntityTarget<ObjectLiteral> {
  const entityTarget = entityRegistry.get(tableKey);

  if (!entityTarget) {
    throw new Error(
      `Unknown seed table key "${tableKey}". Register it in the entityRegistry passed to discoverSeedDataFiles().`,
    );
  }

  return entityTarget;
}

/**
 * Recursively collect all file paths under a directory.
 * @param directoryPath Root directory to scan.
 * @returns Collected absolute or joined file paths.
 */
function collectFilePathsRecursively(directoryPath: string): Array<string> {
  const discoveredFilePaths: Array<string> = [];
  const directoryEntries = readdirSync(directoryPath, { withFileTypes: true });

  for (const directoryEntry of directoryEntries) {
    const fullPath = pathModule.join(directoryPath, directoryEntry.name);

    if (directoryEntry.isDirectory()) {
      discoveredFilePaths.push(...collectFilePathsRecursively(fullPath));
    }

    if (directoryEntry.isFile()) {
      discoveredFilePaths.push(fullPath);
    }
  }

  return discoveredFilePaths;
}

/**
 * Check whether a path matches supported seed file naming and extension rules.
 * @param filePath File path to validate.
 * @returns True when the file is a supported seed data file.
 */
function isSeedDataFilePath(filePath: string): boolean {
  if (!filePath.includes(dataFileSuffix)) {
    return false;
  }

  if (filePath.endsWith('.json')) {
    return true;
  }

  if (filePath.endsWith('.ts')) {
    return isTsRuntimeMode;
  }

  if (filePath.endsWith('.js')) {
    return !isTsRuntimeMode;
  }

  return false;
}

/**
 * Validate and normalize a loaded seed data object.
 * @param rawDataFile Raw module or JSON export.
 * @param filePath Source file path for error context.
 * @param entityRegistry Caller-provided table-key-to-entity mapping.
 * @returns Normalized seed data file with resolved entity target.
 */
function normalizeLoadedSeedDataFile(
  rawDataFile: unknown,
  filePath: string,
  entityRegistry: ReadonlyMap<string, EntityTarget<ObjectLiteral>>,
): SeedDataFile {
  if (!isRecord(rawDataFile)) {
    throw new TypeError(
      `Seed data file "${filePath}" did not export an object.`,
    );
  }

  const { id, order, data, schema, table, tags } = rawDataFile;

  if (typeof id !== 'string' || id.trim().length === 0) {
    throw new TypeError(
      `Seed data file "${filePath}" must provide "id" as a non-empty string.`,
    );
  }

  const normalizedOrder = typeof order === 'number' ? order : Number.NaN;

  if (!Number.isFinite(normalizedOrder)) {
    throw new TypeError(
      `Seed data file "${filePath}" must provide "order" as a finite number.`,
    );
  }

  if (!Array.isArray(data)) {
    throw new TypeError(
      `Seed data file "${filePath}" must provide "data" as an array.`,
    );
  }

  if (data.some((row) => !isRecord(row))) {
    throw new TypeError(
      `Seed data file "${filePath}" has invalid "data" rows. Expected objects.`,
    );
  }

  if (
    tags !== undefined &&
    (!Array.isArray(tags) ||
      tags.some((tag) => typeof tag !== 'string' || tag.trim().length === 0))
  ) {
    throw new Error(
      `Seed data file "${filePath}" has invalid "tags". Expected an array of non-empty strings.`,
    );
  }

  if (!table) {
    throw new TypeError(`Seed data file "${filePath}" must provide "table".`);
  }

  if (
    typeof table !== 'string' &&
    typeof table !== 'function' &&
    !isRecord(table)
  ) {
    throw new TypeError(
      `Seed data file "${filePath}" has invalid "table". Expected a table key string or entity target.`,
    );
  }

  const normalizedSchema = parseSchema(schema, filePath);

  const tableEntity =
    typeof table === 'string'
      ? resolveSeedEntity(table, entityRegistry)
      : (table as EntityTarget<ObjectLiteral>);
  const normalizedId = id.trim();
  const normalizedTags = Array.isArray(tags)
    ? tags.map((tag) => tag.trim())
    : undefined;

  return {
    data: data as Array<Record<string, unknown>>,
    id: normalizedId,
    order: normalizedOrder,
    schema: normalizedSchema,
    table: tableEntity,
    tags: normalizedTags,
  };
}

/**
 * Load a seed data file from JS, TS, or JSON source.
 * @param filePath Seed file path.
 * @param entityRegistry Caller-provided table-key-to-entity mapping.
 * @returns Parsed and normalized seed data file object.
 */
function loadSeedDataFile(
  filePath: string,
  entityRegistry: ReadonlyMap<string, EntityTarget<ObjectLiteral>>,
): SeedDataFile {
  const loadedModule = nodeRequire(filePath) as {
    default?: unknown;
    seedDataFile?: unknown;
  };
  const rawDataFile =
    loadedModule.seedDataFile ?? loadedModule.default ?? loadedModule;

  if (!rawDataFile) {
    throw new Error(
      `Seed data file "${filePath}" must export "seedDataFile", default export, or a JSON object.`,
    );
  }

  return normalizeLoadedSeedDataFile(rawDataFile, filePath, entityRegistry);
}

/**
 * Discover and load seed data files from a directory.
 * @param dataDirectoryPath Root directory containing seed files.
 * @param entityRegistry Table-key-to-entity mapping used to resolve `table` fields in seed JSON files.
 * @returns Sorted seed data file list.
 */
export async function discoverSeedDataFiles(
  dataDirectoryPath: string,
  entityRegistry: ReadonlyMap<string, EntityTarget<ObjectLiteral>>,
): Promise<Array<SeedDataFile>> {
  const absoluteDataDirectoryPath = pathModule.resolve(dataDirectoryPath);

  if (!existsSync(absoluteDataDirectoryPath)) {
    throw new Error(
      `Seed data directory does not exist: ${absoluteDataDirectoryPath}`,
    );
  }

  const filePaths = collectFilePathsRecursively(absoluteDataDirectoryPath)
    .filter((filePath) => isSeedDataFilePath(filePath))
    .sort((leftPath, rightPath) => leftPath.localeCompare(rightPath));

  const loadedSeedDataFiles = filePaths.map((filePath) => ({
    filePath,
    seedDataFile: loadSeedDataFile(filePath, entityRegistry),
  }));

  validateUniqueSeedIds(loadedSeedDataFiles);
  const seedDataFiles = loadedSeedDataFiles.map(
    (fileEntry) => fileEntry.seedDataFile,
  );

  return seedDataFiles.sort(
    (leftDataFile, rightDataFile) =>
      leftDataFile.order - rightDataFile.order ||
      leftDataFile.id.localeCompare(rightDataFile.id),
  );
}

import { Logger } from '@nestjs/common';
import {
  DataSource,
  DeepPartial,
  EntityManager,
  ObjectLiteral,
  Repository,
} from 'typeorm';
import {
  buildEntityIndex,
  buildKeyFromInputRow,
} from '@/seeding/core/seed-key.helper';
import {
  SeedContext,
  SeedDataFile,
  SeedFieldMapping,
  SeedReferenceMapping,
} from '@/seeding/core/seed-runner.types';

class UnresolvedSelfReferenceError extends Error {
  public constructor(
    public readonly dependencyKey: string,
    public readonly targetColumn: string,
  ) {
    super(
      `Self reference "${targetColumn}" could not be resolved yet for key ${dependencyKey}.`,
    );
  }
}

/**
 * Serialize unknown errors into log-friendly strings.
 * @param error Unknown thrown value.
 * @returns Error stack when available, otherwise a string value.
 */
function formatErrorForLog(error: unknown): string {
  return error instanceof Error ? error.stack ?? error.message : String(error);
}

/**
 * Resolve relation names required for loading table keys and explicit relation hints.
 * @param seedDataFile Seed data file descriptor.
 * @returns Relation names to load.
 */
function getRelationNames(seedDataFile: SeedDataFile): Array<string> {
  const relationNames = new Set(seedDataFile.schema.tableRelationsToLoad ?? []);

  for (const keyColumn of seedDataFile.schema.tableKeyColumns) {
    if (keyColumn.includes('.')) {
      const [relationName] = keyColumn.split('.');
      relationNames.add(relationName);
    }
  }

  return [...relationNames];
}

/**
 * Convert relation names into a TypeORM string array for nested relation loading.
 * TypeORM's find() accepts dot-notation nested relations as a string array
 * (e.g. ["relation", "relation.nested"]) but not as a flat object.
 * @param relationNames Relation names to load.
 * @returns TypeORM relations string array.
 */
function buildRelationsObject(relationNames: Array<string>): Array<string> {
  return relationNames;
}

/**
 * Load existing rows for a seed table, including required relations when needed.
 * @param repository Table repository.
 * @param seedDataFile Seed file descriptor.
 * @returns Existing rows from database.
 */
async function loadExistingRows(
  repository: Repository<ObjectLiteral>,
  seedDataFile: SeedDataFile,
): Promise<Array<ObjectLiteral>> {
  const relationNames = getRelationNames(seedDataFile);

  if (relationNames.length === 0) {
    return repository.find();
  }

  return repository.find({ relations: buildRelationsObject(relationNames) });
}

/**
 * Deduplicate source rows based on configured input key columns.
 * @param rows Source rows.
 * @param inputKeyColumns Input key columns.
 * @returns Deduplicated source rows.
 */
function deduplicateRows(
  rows: Array<Record<string, unknown>>,
  inputKeyColumns: Array<string>,
): Array<Record<string, unknown>> {
  const uniqueRows = new Map<string, Record<string, unknown>>();

  for (const row of rows) {
    uniqueRows.set(buildKeyFromInputRow(row, inputKeyColumns), row);
  }

  return [...uniqueRows.values()];
}

/**
 * Find key columns that are not present in the source row.
 * @param sourceRow Source row.
 * @param keyColumns Key columns to check.
 * @returns Missing key columns.
 */
function findMissingColumns(
  sourceRow: Record<string, unknown>,
  keyColumns: Array<string>,
): Array<string> {
  return keyColumns.filter((keyColumn) => !(keyColumn in sourceRow));
}

/**
 * Resolve a referenced dependency entity for a source row.
 * @param context Seed execution context.
 * @param seedDataFileId Current seed data file id.
 * @param targetColumn Current target column in mapping.
 * @param mapping Reference mapping definition.
 * @param sourceRow Current source row.
 * @returns Referenced entity object.
 */
function resolveDependencyEntity(
  context: SeedContext,
  seedDataFileId: string,
  targetColumn: string,
  mapping: SeedReferenceMapping,
  sourceRow: Record<string, unknown>,
): ObjectLiteral | undefined {
  const missingKeyColumns = findMissingColumns(sourceRow, mapping.keyColumns);

  if (missingKeyColumns.length > 0) {
    if (mapping.optional) {
      return undefined;
    }

    throw new Error(
      `Seed file "${seedDataFileId}" row is missing key columns [${missingKeyColumns.join(', ')}] for reference mapping "${targetColumn}".`,
    );
  }

  const hasEmptyKeyValue = mapping.keyColumns.some((keyColumn) => {
    const keyValue = sourceRow[keyColumn];
    return (
      keyValue === null ||
      keyValue === undefined ||
      (typeof keyValue === 'string' && keyValue.trim() === '')
    );
  });

  if (hasEmptyKeyValue) {
    if (mapping.optional) {
      return undefined;
    }

    throw new Error(
      `Seed file "${seedDataFileId}" row has empty key column values for reference mapping "${targetColumn}".`,
    );
  }

  const dependencyIndex = context.get(mapping.dataFileId);
  const dependencyKey = buildKeyFromInputRow(sourceRow, mapping.keyColumns);

  if (!dependencyIndex) {
    if (mapping.dataFileId === seedDataFileId) {
      throw new UnresolvedSelfReferenceError(dependencyKey, targetColumn);
    }

    throw new Error(
      `Dependency data file "${mapping.dataFileId}" is not loaded yet. Check data file order.`,
    );
  }

  const dependencyEntity = dependencyIndex.get(dependencyKey);

  if (!dependencyEntity) {
    if (mapping.dataFileId === seedDataFileId) {
      throw new UnresolvedSelfReferenceError(dependencyKey, targetColumn);
    }

    throw new Error(
      `Dependency "${mapping.dataFileId}" row not found for key ${dependencyKey}.`,
    );
  }

  return dependencyEntity;
}

/**
 * Resolve one mapped field value from source row and context.
 * @param context Seed execution context.
 * @param seedDataFileId Current seed data file id.
 * @param targetColumn Current target column in mapping.
 * @param mapping Field mapping definition.
 * @param sourceRow Current source row.
 * @returns Resolved mapped value.
 */
function resolveMappedValue(
  context: SeedContext,
  seedDataFileId: string,
  targetColumn: string,
  mapping: SeedFieldMapping,
  sourceRow: Record<string, unknown>,
): unknown {
  if (mapping.type === 'column') {
    if (!(mapping.sourceColumn in sourceRow)) {
      throw new Error(
        `Seed file "${seedDataFileId}" row is missing source column "${mapping.sourceColumn}" for target "${targetColumn}".`,
      );
    }

    return sourceRow[mapping.sourceColumn];
  }

  if (mapping.type === 'constant') {
    return mapping.value;
  }

  return resolveDependencyEntity(
    context,
    seedDataFileId,
    targetColumn,
    mapping,
    sourceRow,
  );
}

/**
 * Map a source row into an entity payload according to mapping schema.
 * @param context Seed execution context.
 * @param seedDataFile Seed descriptor containing mapping schema.
 * @param sourceRow Current source row.
 * @returns Mapped entity payload.
 */
function mapRowToPayload(
  context: SeedContext,
  seedDataFile: SeedDataFile,
  sourceRow: Record<string, unknown>,
): DeepPartial<ObjectLiteral> {
  const payload: DeepPartial<ObjectLiteral> = {};

  for (const [targetColumn, mapping] of Object.entries(
    seedDataFile.schema.mapping,
  )) {
    payload[targetColumn] = resolveMappedValue(
      context,
      seedDataFile.id,
      targetColumn,
      mapping,
      sourceRow,
    );
  }

  return payload;
}

/**
 * Build a source-row-key to final-entity index after seeding.
 * @param finalEntityIndex Final entity index by table key.
 * @param seedDataFile Seed descriptor.
 * @param sourceRows Original source rows.
 * @returns Source-key-to-entity lookup map.
 */
function buildSourceToEntityIndex(
  finalEntityIndex: Map<string, ObjectLiteral>,
  seedDataFile: SeedDataFile,
  sourceRows: Array<Record<string, unknown>>,
): Map<string, ObjectLiteral> {
  const sourceToEntityIndex = new Map<string, ObjectLiteral>();

  for (const sourceRow of sourceRows) {
    const sourceKey = buildKeyFromInputRow(
      sourceRow,
      seedDataFile.schema.inputKeyColumns,
    );
    const matchedEntity = finalEntityIndex.get(sourceKey);

    if (!matchedEntity) {
      throw new Error(
        `Row from "${seedDataFile.id}" was not found after seeding for key ${sourceKey}.`,
      );
    }

    sourceToEntityIndex.set(sourceKey, matchedEntity);
  }

  return sourceToEntityIndex;
}

/**
 * Build a partial source-row-key to entity index for rows already present.
 * Used while inserting self-referencing rows in multiple passes.
 * @param finalEntityIndex Final entity index by table key.
 * @param seedDataFile Seed descriptor.
 * @param sourceRows Original source rows.
 * @returns Source-key-to-entity lookup map for available rows only.
 */
function buildAvailableSourceToEntityIndex(
  finalEntityIndex: Map<string, ObjectLiteral>,
  seedDataFile: SeedDataFile,
  sourceRows: Array<Record<string, unknown>>,
): Map<string, ObjectLiteral> {
  const sourceToEntityIndex = new Map<string, ObjectLiteral>();

  for (const sourceRow of sourceRows) {
    const sourceKey = buildKeyFromInputRow(
      sourceRow,
      seedDataFile.schema.inputKeyColumns,
    );
    const matchedEntity = finalEntityIndex.get(sourceKey);

    if (matchedEntity) {
      sourceToEntityIndex.set(sourceKey, matchedEntity);
    }
  }

  return sourceToEntityIndex;
}

/**
 * Insert self-referencing rows in passes so parent rows can be persisted first.
 * @param repository Table repository.
 * @param context Seed execution context.
 * @param seedDataFile Seed descriptor.
 * @param sourceRows Deduplicated source rows.
 * @param existingRows Existing table rows.
 * @param existingRowIndex Existing row index by table key.
 * @returns Final rows and insert count after all passes complete.
 */
async function insertRowsWithSelfReferences(
  repository: Repository<ObjectLiteral>,
  context: SeedContext,
  seedDataFile: SeedDataFile,
  sourceRows: Array<Record<string, unknown>>,
  existingRows: Array<ObjectLiteral>,
  existingRowIndex: Map<string, ObjectLiteral>,
): Promise<{ finalRows: Array<ObjectLiteral>; insertedRowCount: number }> {
  let insertedRowCount = 0;
  let finalRows = existingRows;
  let finalRowIndex = existingRowIndex;
  const pendingSourceRows = sourceRows.filter((sourceRow) => {
    const sourceKey = buildKeyFromInputRow(
      sourceRow,
      seedDataFile.schema.inputKeyColumns,
    );

    return !existingRowIndex.has(sourceKey);
  });

  context.set(
    seedDataFile.id,
    buildAvailableSourceToEntityIndex(finalRowIndex, seedDataFile, sourceRows),
  );

  /**
   * Process one self-reference insertion pass and recurse until all rows resolve.
   * @param currentPendingSourceRows Source rows still waiting on self references.
   * @returns Promise resolved when all pending rows are inserted.
   */
  async function processPendingRows(
    currentPendingSourceRows: Array<Record<string, unknown>>,
  ): Promise<void> {
    if (currentPendingSourceRows.length === 0) {
      return;
    }

    const rowsToInsert: Array<DeepPartial<ObjectLiteral>> = [];
    const remainingSourceRows: Array<Record<string, unknown>> = [];
    let firstUnresolvedReference: UnresolvedSelfReferenceError | undefined;

    for (const sourceRow of currentPendingSourceRows) {
      let rowToInsert: DeepPartial<ObjectLiteral> | undefined;

      try {
        rowToInsert = mapRowToPayload(context, seedDataFile, sourceRow);
      } catch (error) {
        if (error instanceof UnresolvedSelfReferenceError) {
          remainingSourceRows.push(sourceRow);
          firstUnresolvedReference ??= error;
        } else {
          throw error;
        }
      }

      if (rowToInsert !== undefined) {
        rowsToInsert.push(rowToInsert);
      }
    }

    if (rowsToInsert.length === 0) {
      throw new Error(
        `Seed file "${seedDataFile.id}" has an unresolved self-reference for "${firstUnresolvedReference?.targetColumn ?? 'unknown'}" with key ${firstUnresolvedReference?.dependencyKey ?? 'unknown'}. Ensure parent rows appear earlier in the same file or already exist in the database.`,
      );
    }

    await repository.save(rowsToInsert, { chunk: 500 });
    insertedRowCount += rowsToInsert.length;
    finalRows = await loadExistingRows(repository, seedDataFile);
    finalRowIndex = buildEntityIndex(
      finalRows,
      seedDataFile.schema.tableKeyColumns,
    );

    context.set(
      seedDataFile.id,
      buildAvailableSourceToEntityIndex(
        finalRowIndex,
        seedDataFile,
        sourceRows,
      ),
    );

    await processPendingRows(remainingSourceRows);
  }

  await processPendingRows(pendingSourceRows);

  return { finalRows, insertedRowCount };
}

/**
 * Run one seed data file end-to-end.
 * @param context Seed execution context.
 * @param entityManager Transaction-scoped TypeORM entity manager.
 * @param logger Nest logger instance.
 * @param seedDataFile Seed file descriptor.
 * @returns Promise resolved when file processing is complete.
 */
async function runOneDataFile(
  context: SeedContext,
  entityManager: EntityManager,
  logger: Logger,
  seedDataFile: SeedDataFile,
): Promise<void> {
  const repository = entityManager.getRepository(seedDataFile.table);
  const sourceRows = deduplicateRows(
    seedDataFile.data,
    seedDataFile.schema.inputKeyColumns,
  );

  const existingRows = await loadExistingRows(repository, seedDataFile);
  const existingRowIndex = buildEntityIndex(
    existingRows,
    seedDataFile.schema.tableKeyColumns,
  );
  const hasSelfReference = Object.values(seedDataFile.schema.mapping).some(
    (mapping) =>
      mapping.type === 'reference' && mapping.dataFileId === seedDataFile.id,
  );

  let insertedRowCount = 0;
  let finalRows = existingRows;
  let finalRowIndex = existingRowIndex;

  if (hasSelfReference) {
    const insertionResult = await insertRowsWithSelfReferences(
      repository,
      context,
      seedDataFile,
      sourceRows,
      existingRows,
      existingRowIndex,
    );
    finalRows = insertionResult.finalRows;
    insertedRowCount = insertionResult.insertedRowCount;
    finalRowIndex = buildEntityIndex(
      finalRows,
      seedDataFile.schema.tableKeyColumns,
    );
  } else {
    const rowsToInsert: Array<DeepPartial<ObjectLiteral>> = [];

    for (const sourceRow of sourceRows) {
      const sourceKey = buildKeyFromInputRow(
        sourceRow,
        seedDataFile.schema.inputKeyColumns,
      );

      if (!existingRowIndex.has(sourceKey)) {
        rowsToInsert.push(mapRowToPayload(context, seedDataFile, sourceRow));
      }
    }

    if (rowsToInsert.length > 0) {
      await repository.save(rowsToInsert, { chunk: 500 });
      insertedRowCount = rowsToInsert.length;
      finalRows = await loadExistingRows(repository, seedDataFile);
      finalRowIndex = buildEntityIndex(
        finalRows,
        seedDataFile.schema.tableKeyColumns,
      );
    }
  }

  context.set(
    seedDataFile.id,
    buildSourceToEntityIndex(finalRowIndex, seedDataFile, sourceRows),
  );

  logger.log(
    `[${seedDataFile.id}] inserted ${insertedRowCount}, total loaded ${finalRows.length}.`,
  );
}

/**
 * Execute seed files sequentially to honor dependency order.
 * @param context Seed execution context.
 * @param entityManager Transaction-scoped TypeORM entity manager.
 * @param logger Nest logger instance.
 * @param seedDataFiles Seed file list.
 * @returns Promise resolved when all files are processed.
 */
async function runDataFilesSequentially(
  context: SeedContext,
  entityManager: EntityManager,
  logger: Logger,
  seedDataFiles: Array<SeedDataFile>,
): Promise<void> {
  let executionPromise = Promise.resolve();

  for (const seedDataFile of seedDataFiles) {
    executionPromise = executionPromise.then(() =>
      runOneDataFile(context, entityManager, logger, seedDataFile),
    );
  }

  await executionPromise;
}

/**
 * Validate that selected seed files are ordered so all references are available.
 * @param seedDataFiles Seed files selected for execution.
 */
export function validateSeedOrder(seedDataFiles: Array<SeedDataFile>): void {
  const completedDataFileIds = new Set<string>();
  const selectedDataFileIds = new Set(
    seedDataFiles.map((seedDataFile) => seedDataFile.id),
  );

  for (const seedDataFile of seedDataFiles) {
    for (const mapping of Object.values(seedDataFile.schema.mapping)) {
      if (mapping.type === 'reference') {
        if (!selectedDataFileIds.has(mapping.dataFileId)) {
          throw new Error(
            `Seed file "${seedDataFile.id}" references "${mapping.dataFileId}" which is not selected.`,
          );
        }

        if (
          mapping.dataFileId !== seedDataFile.id &&
          !completedDataFileIds.has(mapping.dataFileId)
        ) {
          throw new Error(
            `Seed file "${seedDataFile.id}" references "${mapping.dataFileId}" before it is executed. Fix "order" values.`,
          );
        }
      }
    }

    completedDataFileIds.add(seedDataFile.id);
  }
}

/**
 * Filter seed files by selectors (`all`, seed id, or tag).
 * @param seedDataFiles Available seed files.
 * @param selectors Selector list.
 * @returns Filtered seed files.
 */
export function filterDataFiles(
  seedDataFiles: Array<SeedDataFile>,
  selectors: Array<string>,
): Array<SeedDataFile> {
  if (selectors.length === 0 || selectors.includes('all')) {
    return seedDataFiles;
  }

  const selectorSet = new Set(selectors);

  return seedDataFiles.filter(
    (seedDataFile) =>
      selectorSet.has(seedDataFile.id) ||
      (seedDataFile.tags ?? []).some((tag) => selectorSet.has(tag)),
  );
}

/**
 * Execute all selected seed files inside one explicit transaction.
 * @param dataSource Initialized TypeORM data source.
 * @param logger Nest logger instance.
 * @param seedDataFiles Seed files selected for execution.
 * @returns Promise resolved after commit.
 */
export async function executeSeedTransaction(
  dataSource: DataSource,
  logger: Logger,
  seedDataFiles: Array<SeedDataFile>,
): Promise<void> {
  const queryRunner = dataSource.createQueryRunner();
  await queryRunner.connect();
  await queryRunner.startTransaction();

  try {
    const context: SeedContext = new Map<string, Map<string, ObjectLiteral>>();
    await runDataFilesSequentially(
      context,
      queryRunner.manager,
      logger,
      seedDataFiles,
    );
    await queryRunner.commitTransaction();
  } catch (error) {
    if (queryRunner.isTransactionActive) {
      await queryRunner.rollbackTransaction();
    }

    logger.error(
      'Seeding failed. All changes from this run were rolled back.',
      formatErrorForLog(error),
    );
    throw error;
  } finally {
    await queryRunner.release();
  }
}

import { ObjectLiteral } from 'typeorm';

/**
 * Normalize composite-key parts to stable serializable values.
 * @param value Raw key value.
 * @returns Normalized key value.
 */
function normalizeKeyPart(value: unknown): unknown {
  if (value instanceof Date) {
    return value.toISOString();
  }

  if (typeof value === 'object' && value && 'id' in value) {
    return (value as { id: unknown }).id;
  }

  return value ?? undefined;
}

/**
 * Serialize multiple key parts into a deterministic composite key.
 * @param keyParts Ordered key parts.
 * @returns Serialized composite key string.
 */
function serializeCompositeKey(keyParts: Array<unknown>): string {
  return JSON.stringify(keyParts.map((part) => normalizeKeyPart(part)));
}

/**
 * Read a nested property value using dot-notation path syntax.
 * @param sourceObject Source object to traverse.
 * @param pathString Dot-notation path (for example: relation.field).
 * @returns Nested value or undefined.
 */
function getNestedValue(
  sourceObject: ObjectLiteral,
  pathString: string,
): unknown {
  const pathSegments = pathString.split('.');
  let currentValue: unknown = sourceObject;

  for (const pathSegment of pathSegments) {
    if (currentValue === null || typeof currentValue !== 'object') {
      return undefined;
    }

    currentValue = (currentValue as Record<string, unknown>)[pathSegment];
  }

  return currentValue;
}

/**
 * Build a serialized key from a source input row.
 * @param inputRow Source row object.
 * @param keyColumns Column names to include in key.
 * @returns Serialized key string.
 */
export function buildKeyFromInputRow(
  inputRow: Record<string, unknown>,
  keyColumns: Array<string>,
): string {
  return serializeCompositeKey(
    keyColumns.map((keyColumn) => inputRow[keyColumn]),
  );
}

/**
 * Build a serialized key from an existing entity object.
 * @param entity Entity instance.
 * @param keyColumns Entity key columns (supports dot notation).
 * @returns Serialized key string.
 */
export function buildKeyFromEntity(
  entity: ObjectLiteral,
  keyColumns: Array<string>,
): string {
  return serializeCompositeKey(
    keyColumns.map((keyColumn) => getNestedValue(entity, keyColumn)),
  );
}

/**
 * Build an entity lookup index by composite key.
 * @param entities Entity list to index.
 * @param keyColumns Key definition for index entries.
 * @returns Composite-key-to-entity lookup map.
 */
export function buildEntityIndex(
  entities: Array<ObjectLiteral>,
  keyColumns: Array<string>,
): Map<string, ObjectLiteral> {
  return new Map<string, ObjectLiteral>(
    entities.map((entity) => [buildKeyFromEntity(entity, keyColumns), entity]),
  );
}

import { Logger } from '@nestjs/common';
import { DataSource } from 'typeorm';
import {
  executeSeedTransaction,
  filterDataFiles,
  validateSeedOrder,
} from '@/seeding/core/seed-execution.helper';
import type { SeedDataFile } from '@/seeding/core/seed-runner.types';

export {
  SeedColumnMapping,
  SeedConstantMapping,
  SeedDataSchema,
  SeedFieldMapping,
  SeedReferenceMapping,
} from '@/seeding/core/seed-runner.types';
export type { SeedDataFile } from '@/seeding/core/seed-runner.types';
export { discoverSeedDataFiles } from '@/seeding/core/seed-discovery.helper';

/**
 * Execute selected seed data files with connection lifecycle handling.
 * @param parameters Execution parameters container.
 * @param parameters.dataSource TypeORM data source.
 * @param parameters.logger Nest logger instance.
 * @param parameters.seedDataFiles Available seed files.
 * @param parameters.selectors Optional selector list.
 * @returns Promise resolved when seeding is complete.
 */
export async function runSeedDataFiles(parameters: {
  dataSource: DataSource;
  logger: Logger;
  seedDataFiles: Array<SeedDataFile>;
  selectors?: Array<string>;
}): Promise<void> {
  const { dataSource, logger, seedDataFiles } = parameters;
  const selectors = parameters.selectors ?? [];
  const selectedDataFiles = filterDataFiles(seedDataFiles, selectors);

  if (selectedDataFiles.length === 0) {
    logger.warn('No seed data files matched the selected filters.');
    return;
  }

  validateSeedOrder(selectedDataFiles);

  const shouldDestroyConnection = !dataSource.isInitialized;

  if (shouldDestroyConnection) {
    await dataSource.initialize();
  }

  try {
    await executeSeedTransaction(dataSource, logger, selectedDataFiles);
  } finally {
    if (shouldDestroyConnection && dataSource.isInitialized) {
      await dataSource.destroy();
    }
  }
}

import { EntityTarget, ObjectLiteral } from 'typeorm';

export interface SeedColumnMapping {
  sourceColumn: string;
  type: 'column';
}

export interface SeedConstantMapping {
  type: 'constant';
  value: unknown;
}

export interface SeedReferenceMapping {
  dataFileId: string;
  keyColumns: Array<string>;
  optional?: boolean;
  type: 'reference';
}

export type SeedFieldMapping =
  | SeedColumnMapping
  | SeedConstantMapping
  | SeedReferenceMapping;

export interface SeedDataSchema {
  inputKeyColumns: Array<string>;
  mapping: Record<string, SeedFieldMapping>;
  tableKeyColumns: Array<string>;
  tableRelationsToLoad?: Array<string>;
}

